&lt;br /&gt;&lt;br /&gt;&lt;table id=&quot;TocContainerTable&quot;&gt;&lt;tr&gt;&lt;td&gt;&lt;div id=&quot;TocContainer&quot;&gt;&lt;p class=&quot;small&quot;&gt;&lt;b&gt;Table of Contents&lt;/b&gt;&lt;span id=&quot;ExpandTocSpan&quot;&gt; [&lt;a href=&quot;#&quot; onclick=&quot;javascript:if(document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]==&#39;none&#39;) document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;&#39;; else document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;none&#39;; return false;&quot;&gt;Hide/Show&lt;/a&gt;]&lt;/span&gt;&lt;/p&gt;&lt;div id=&quot;Toc&quot;&gt;&lt;p&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#La_monnaie_0&quot;&gt; La monnaie &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#La_revente_du_butin_1&quot;&gt; La revente du butin &lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Richesses_non_mon&#233;taires_2&quot;&gt; Richesses non mon&#233;taires &lt;/a&gt;&lt;br /&gt;&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;Chaque personnage d&#233;bute avec un certain nombre de pi&#232;ces d’or qu’il peut d&#233;penser pour acheter des armes, des armures et d’autres pi&#232;ces d’&#233;quipement. Au fil de ses aventures, le personnage accumule des richesses qu’il peut d&#233;penser pour se procurer des objets magiques et am&#233;liorer la qualit&#233; de son &#233;quipement. La table suivante indique le nombre de pi&#232;ces d’or dont chaque &lt;a class=&quot;pagelink&quot; href=&quot;Classes.html&quot; title=&quot;classe&quot;&gt;classe&lt;/a&gt; dispose au d&#233;part. De plus, le personnage d&#233;bute avec des v&#234;tements d’une valeur de 10 po ou moins. Pour les personnages de niveau sup&#233;rieur &#224; 1, consultez plut&#244;t le &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Des-Pnj.html#EQUIPEMENTPNJ&quot; title=&quot;Cr&#233;er des PNJ&quot;&gt;tableau d&#39;&#233;quipement des PNJ&lt;/a&gt; ou le &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres.html#TABLERICHESSEPJPARNIVEAU&quot; title=&quot;Les rencontres&quot;&gt;tableau des richesses par niveau&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;a name=&quot;TABLERICHESSEDEPARTPJ&quot;&gt;&lt;/a&gt;
&lt;center&gt;
&lt;table CLASS=&quot;tablo&quot;&gt;&lt;caption&gt;Richesse de d&#233;part des personnages&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Classe&lt;/td&gt;&lt;td&gt;Source&lt;/td&gt;&lt;td&gt;Richesse de d&#233;part (po)&lt;/td&gt;&lt;td&gt;Moyenne (po)&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arcaniste.html&quot; title=&quot;L&amp;#39;arcaniste&quot;&gt;Arcaniste&lt;/a&gt;&lt;/td&gt;&lt;td&gt;MCA&lt;/td&gt;&lt;td&gt;2d6&#215;10&lt;/td&gt;&lt;td&gt;70&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;Alchimiste&lt;/a&gt;&lt;/td&gt;&lt;td&gt;MJRA&lt;/td&gt;&lt;td&gt;3d6&#215;10&lt;/td&gt;&lt;td&gt;105&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html&quot; title=&quot;Le barbare&quot;&gt;Barbare&lt;/a&gt;&lt;/td&gt;&lt;td&gt;MJ&lt;/td&gt;&lt;td&gt;3d6x10&lt;/td&gt;&lt;td&gt;105&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barde.html&quot; title=&quot;Le barde&quot;&gt;Barde&lt;/a&gt;&lt;/td&gt;&lt;td&gt;MJ&lt;/td&gt;&lt;td&gt;3d6x10&lt;/td&gt;&lt;td&gt;105&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bretteur.html&quot; title=&quot;Le bretteur&quot;&gt;Bretteur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;MCA&lt;/td&gt;&lt;td&gt;5d6&#215;10&lt;/td&gt;&lt;td&gt;175&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chaman.html&quot; title=&quot;Le chaman&quot;&gt;Chaman&lt;/a&gt;&lt;/td&gt;&lt;td&gt;MCA&lt;/td&gt;&lt;td&gt;3d6&#215;10&lt;/td&gt;&lt;td&gt;105&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur.html&quot; title=&quot;Le chasseur&quot;&gt;Chasseur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;MCA&lt;/td&gt;&lt;td&gt;4d6&#215;10&lt;/td&gt;&lt;td&gt;140&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier.html&quot; title=&quot;Le chevalier&quot;&gt;Chevalier&lt;/a&gt;&lt;/td&gt;&lt;td&gt;MJRA&lt;/td&gt;&lt;td&gt;5d6&#215;10&lt;/td&gt;&lt;td&gt;175&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cin&#233;tiste.html&quot; title=&quot;Le cin&#233;tiste&quot;&gt;Cin&#233;tiste&lt;/a&gt;&lt;/td&gt;&lt;td&gt;AO&lt;/td&gt;&lt;td&gt;1d6&#215;10&lt;/td&gt;&lt;td&gt;35&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Conjurateur.html&quot; title=&quot;Le conjurateur (aussi appel&#233; invocateur)&quot;&gt;Conjurateur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;MJRA&lt;/td&gt;&lt;td&gt;2d6&#215;10&lt;/td&gt;&lt;td&gt;70&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;Druide&lt;/a&gt;&lt;/td&gt;&lt;td&gt;MJ&lt;/td&gt;&lt;td&gt;2d6x10&lt;/td&gt;&lt;td&gt;70&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enqu&#234;teur.html&quot; title=&quot;L&amp;#39;enqu&#234;teur&quot;&gt;Enqu&#234;teur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;MCA&lt;/td&gt;&lt;td&gt;3d6&#215;10&lt;/td&gt;&lt;td&gt;105&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ensorceleur.html&quot; title=&quot;L&amp;#39;ensorceleur&quot;&gt;Ensorceleur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;MJ&lt;/td&gt;&lt;td&gt;2d6x10&lt;/td&gt;&lt;td&gt;70&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html&quot; title=&quot;Le guerrier&quot;&gt;Guerrier&lt;/a&gt;&lt;/td&gt;&lt;td&gt;MJ&lt;/td&gt;&lt;td&gt;5d6x10&lt;/td&gt;&lt;td&gt;175&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Hypnotiseur.html&quot; title=&quot;L&amp;#39;hypnotiseur&quot;&gt;Hypnotiseur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;AO&lt;/td&gt;&lt;td&gt;3d6&#215;10&lt;/td&gt;&lt;td&gt;105&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&q